QUESTIONS.push(

  // ================= Mobile Platforms & Devices (50) =================
  { id: "mp-01", topic: "mobile-platforms", q: "A PDA (Personal Digital Assistant) was best described as:", options: ["A modern 5G smartphone", "An early handheld device for personal information management (calendar, contacts, notes) that predated modern smartphones", "A type of cellular base station", "A desktop operating system"], answer: 1, exp: "PDAs (e.g., PalmPilot, early Pocket PCs) later merged with cellular phones to form what we now call smartphones." },
  { id: "mp-02", topic: "mobile-platforms", q: "A smartphone differs from a feature phone mainly in that a smartphone:", options: ["Cannot make phone calls", "Runs a general-purpose OS supporting installable third-party apps, unlike a feature phone's limited, mostly fixed functionality", "Has no touchscreen", "Is only used for gaming"], answer: 1, exp: "Feature phones typically ship with fixed, vendor-provided functionality and little to no app ecosystem." },
  { id: "mp-03", topic: "mobile-platforms", q: "Android's operating system is built on top of which kernel?", options: ["Windows NT kernel", "The Linux kernel", "The Darwin (BSD) kernel", "No kernel — Android runs bare-metal"], answer: 1, exp: "Android uses a modified Linux kernel for core OS services like process and memory management." },
  { id: "mp-04", topic: "mobile-platforms", q: "iOS is:", options: ["An open-source OS usable on any manufacturer's hardware", "Apple's mobile OS, used exclusively on Apple's own hardware in a closed ecosystem", "The same operating system as Android", "A desktop-only operating system"], answer: 1, exp: "Unlike Android's broader licensing to many manufacturers, iOS runs only on Apple-made devices." },
  { id: "mp-05", topic: "mobile-platforms", q: "Android's application framework layer provides:", options: ["Only low-level hardware drivers", "Reusable components (e.g., Activity Manager, Content Providers, View System) that apps are built on top of", "The physical radio hardware", "Nothing — apps talk directly to the Linux kernel"], answer: 1, exp: "This framework sits above the Linux kernel and native libraries, giving app developers higher-level building blocks." },
  { id: "mp-06", topic: "mobile-platforms", q: "The Android Runtime (ART) is responsible for:", options: ["Rendering web pages only", "Executing app bytecode (compiled from Java/Kotlin), using ahead-of-time compilation for performance", "Managing cellular radio signals", "Formatting the device's storage"], answer: 1, exp: "ART replaced the earlier Dalvik runtime, improving app startup and execution performance." },
  { id: "mp-07", topic: "mobile-platforms", q: "iOS's architecture, from the topmost (app-facing) layer downward, is roughly:", options: ["Core OS, Core Services, Media, Cocoa Touch", "Cocoa Touch, Media, Core Services, Core OS", "Media, Cocoa Touch, Core OS, Core Services", "There are no distinct layers in iOS"], answer: 1, exp: "Cocoa Touch provides the UI frameworks apps use directly; Core OS is the lowest, kernel-level layer." },
  { id: "mp-08", topic: "mobile-platforms", q: "App sandboxing on mobile OSes means:", options: ["All apps freely share the same storage and data by default", "Each app is restricted to its own isolated storage/resources, unable to directly access another app's data without explicit permission", "Apps cannot access any device storage at all", "Sandboxing only applies to system apps"], answer: 1, exp: "Sandboxing limits the damage a compromised or malicious app can do to the rest of the system." },
  { id: "mp-09", topic: "mobile-platforms", q: "Runtime permissions (e.g., in Android 6.0+) mean that:", options: ["All permissions are granted automatically at install with no user involvement", "Apps must request sensitive permissions (camera, location, etc.) at the point of use, and the user can grant or deny each one", "Permissions can never be revoked once granted", "Only system apps require any permissions"], answer: 1, exp: "This contrasts with older models that granted all requested permissions in a single bundle at install time." },
  { id: "mp-10", topic: "mobile-platforms", q: "'Android fragmentation' refers to:", options: ["A security vulnerability specific to Android", "The wide variety of device manufacturers, screen sizes, and OS versions in the Android ecosystem, complicating development and testing", "Android's file system being physically fragmented on disk", "A method of speeding up app installation"], answer: 1, exp: "Developers must often test across many device/OS-version combinations to ensure broad compatibility." },
  { id: "mp-11", topic: "mobile-platforms", q: "A SoC (System on Chip) in a mobile device integrates:", options: ["Only the display panel", "CPU, GPU, memory controller, and often the modem, onto a single chip for space and power efficiency", "Only the battery", "Only the camera sensor"], answer: 1, exp: "Integrating these components onto one chip reduces size and power consumption compared to discrete components." },
  { id: "mp-12", topic: "mobile-platforms", q: "An accelerometer sensor in a mobile device measures:", options: ["Ambient light levels", "The device's linear acceleration/motion (e.g., tilt, shake)", "Cellular signal strength", "Screen brightness"], answer: 1, exp: "Accelerometers are commonly used for screen auto-rotation and motion-based gestures." },
  { id: "mp-13", topic: "mobile-platforms", q: "A gyroscope sensor in a mobile device measures:", options: ["Battery charge level", "The device's rotational orientation/angular velocity", "Wi-Fi signal strength", "Touch pressure"], answer: 1, exp: "Combined with the accelerometer, it enables more precise motion tracking (e.g., for gaming or AR)." },
  { id: "mp-14", topic: "mobile-platforms", q: "GPS in a mobile device provides:", options: ["Cellular voice calling", "Geolocation via triangulation of satellite signals", "Wi-Fi connectivity", "Screen touch input"], answer: 1, exp: "GPS is often supplemented by Wi-Fi/cell-tower positioning (assisted GPS) for faster, more accurate fixes indoors." },
  { id: "mp-15", topic: "mobile-platforms", q: "A capacitive touchscreen detects touch by:", options: ["Measuring physical pressure that presses two layers together", "Sensing changes in electrical capacitance caused by a conductive object (like a finger) touching the screen", "Detecting sound waves", "Measuring light reflected off the screen"], answer: 1, exp: "This is why capacitive screens generally don't respond to non-conductive objects like most gloved fingers or plastic styluses." },
  { id: "mp-16", topic: "mobile-platforms", q: "A resistive touchscreen detects touch by:", options: ["Sensing electrical capacitance changes", "Sensing physical pressure that causes two conductive layers to make contact", "Using a camera to track finger position", "Measuring device tilt"], answer: 1, exp: "Resistive screens work with any pointer (gloved finger, stylus) but are generally less sensitive and less capable of multi-touch than capacitive screens." },
  { id: "mp-17", topic: "mobile-platforms", q: "MDM (Mobile Device Management) refers to:", options: ["A cellular network generation", "Enterprise tools/software for managing, securing, and enforcing policy on organization-connected devices", "A mobile app development framework", "A type of touchscreen technology"], answer: 1, exp: "MDM lets IT departments enforce security policies, remotely wipe lost devices, and manage app deployment." },
  { id: "mp-18", topic: "mobile-platforms", q: "BYOD (Bring Your Own Device) is a policy where:", options: ["Employees are prohibited from using personal devices for work", "Employees use their own personal devices for work purposes, raising security/management challenges often addressed by MDM", "Companies issue only company-owned devices", "Devices are shared between all employees"], answer: 1, exp: "BYOD offers convenience/cost savings but requires careful security policy to protect corporate data on personal devices." },
  { id: "mp-19", topic: "mobile-platforms", q: "Apple's App Store review process exists to:", options: ["Automatically approve every submitted app with no review", "Vet apps for compliance with content, security, and quality guidelines before making them available to users", "Only check that an app's file size is small enough", "Charge a one-time fee with no functional review"], answer: 1, exp: "This contrasts with more open distribution models (like Android APK sideloading) that don't require centralized review." },
  { id: "mp-20", topic: "mobile-platforms", q: "Compared to iOS, Android is generally considered a more 'open' platform because it:", options: ["Cannot run any third-party apps", "Allows more customization, source availability, and sideloading apps from outside the official store", "Only runs on Apple hardware", "Has no app store at all"], answer: 1, exp: "iOS restricts installation primarily to its official App Store and offers less system-level customization." },
  { id: "mp-21", topic: "mobile-platforms", q: "Given mobile devices' limited RAM, mobile OSes commonly:", options: ["Never terminate any running app", "Aggressively suspend or terminate background apps (e.g., via a low-memory killer) to free resources for the foreground app", "Increase RAM automatically", "Disable multitasking entirely"], answer: 1, exp: "This memory management approach differs from typical desktop OS behavior, which usually has more RAM headroom." },
  { id: "mp-22", topic: "mobile-platforms", q: "Battery-conscious mobile software design generally aims to:", options: ["Maximize background polling frequency regardless of need", "Minimize unnecessary background wake-ups/polling and use radios/sensors efficiently", "Disable all sensors permanently", "Ignore power consumption entirely"], answer: 1, exp: "Excessive background activity is a common cause of poor battery life on mobile devices." },
  { id: "mp-23", topic: "mobile-platforms", q: "A tablet, compared to a typical smartphone, is generally characterized by:", options: ["A smaller screen and no app ecosystem", "A larger screen with a similar OS/app ecosystem, and often limited or no cellular voice-calling capability", "Running an entirely unrelated operating system", "Lacking any touchscreen"], answer: 1, exp: "Many tablets run the same OS family as phones (e.g., Android or iPadOS) but are optimized for a bigger display." },
  { id: "mp-24", topic: "mobile-platforms", q: "A wearable device like a smartwatch is typically connected to a smartphone via:", options: ["A wired USB cable at all times", "Bluetooth, offloading heavier processing and cellular connectivity to the paired phone", "Only Wi-Fi, never Bluetooth", "A dedicated fiber-optic link"], answer: 1, exp: "Bluetooth's low power consumption suits this kind of always-connected, battery-constrained pairing." },
  { id: "mp-25", topic: "mobile-platforms", q: "Symbian OS is best described as:", options: ["The current market-leading mobile OS", "An early, once-dominant mobile OS (notably used by Nokia) that is now largely obsolete/discontinued", "A modern cross-platform framework", "A cellular network standard"], answer: 1, exp: "Symbian's decline illustrates how quickly mobile platform dominance can shift as newer OSes (iOS, Android) emerged." },
  { id: "mp-26", topic: "mobile-platforms", q: "A cross-device hardware challenge in mobile development is:", options: ["All devices having identical screen size and resolution", "Wide variability in screen size, resolution, and pixel density, requiring apps to support flexible/responsive layouts", "The complete absence of any screen variation", "Devices never changing their hardware over time"], answer: 1, exp: "This variability is especially pronounced on Android given its many manufacturers and device models." },
  { id: "mp-27", topic: "mobile-platforms", q: "A mobile OS's notification system allows apps to:", options: ["Only alert the user while the app is in the foreground", "Alert users (via badges, banners, sounds) even when the app is not actively in the foreground", "Prevent any background communication", "Directly modify other apps' data"], answer: 1, exp: "This is central to features like messaging alerts, reminders, and other timely updates." },
  { id: "mp-28", topic: "mobile-platforms", q: "Common mobile app lifecycle states managed by the OS include:", options: ["Only 'on' and 'off'", "Foreground/active, background/paused, and suspended/terminated", "Only 'installed' and 'uninstalled'", "There is no concept of app lifecycle on mobile OSes"], answer: 1, exp: "The OS transitions apps through these states as the user switches apps or the system needs resources." },
  { id: "mp-29", topic: "mobile-platforms", q: "NFC (Near Field Communication) on a mobile device enables:", options: ["Long-range (multi-kilometer) wireless communication", "Short-range (a few centimeters) wireless communication, commonly used for contactless payments or quick pairing", "GPS positioning", "Cellular voice calls"], answer: 1, exp: "NFC's very short range is a deliberate security/convenience feature for tap-to-use scenarios." },
  { id: "mp-30", topic: "mobile-platforms", q: "Multi-touch capability on a touchscreen allows:", options: ["Only single-finger input ever", "Registering multiple simultaneous touch points, enabling gestures like pinch-to-zoom", "The screen to detect voice commands", "The device to charge wirelessly"], answer: 1, exp: "This requires hardware and software support beyond simple single-point touch detection." },
  { id: "mp-31", topic: "mobile-platforms", q: "A classic PDA (before merging with phones to become smartphones) typically lacked:", options: ["Any storage for contacts/calendar data", "Built-in cellular voice/data capability, since many PDAs were standalone organizers", "Any kind of touchscreen or stylus input", "A processor of any kind"], answer: 1, exp: "PDAs originally focused on personal organization (contacts, calendar, notes) without integrated telephony." },
  { id: "mp-32", topic: "mobile-platforms", q: "Fingerprint or face-unlock on a mobile device is an example of:", options: ["A cellular network feature", "A hardware-backed biometric authentication feature for verifying user identity", "A type of app store review process", "A screen resolution setting"], answer: 1, exp: "Biometric authentication generally offers a convenient, relatively secure alternative to PIN/password entry." },
  { id: "mp-33", topic: "mobile-platforms", q: "The Linux kernel underlying Android provides:", options: ["Only the visual user interface", "Core OS services: process management, memory management, and device drivers", "Only the app store functionality", "Only network browser rendering"], answer: 1, exp: "Higher-level Android components (runtime, framework, apps) build on top of these fundamental kernel services." },
  { id: "mp-34", topic: "mobile-platforms", q: "Android's Hardware Abstraction Layer (HAL) exists to:", options: ["Replace the need for any device drivers", "Provide standard interfaces that expose device hardware capabilities to the higher-level Java API framework", "Directly render the user interface", "Handle billing and payments"], answer: 1, exp: "This abstraction lets the higher framework layers work consistently across devices with different underlying hardware." },
  { id: "mp-35", topic: "mobile-platforms", q: "A 'rooted' Android device (or 'jailbroken' iOS device) has:", options: ["Been permanently disabled by the manufacturer", "Had OS restrictions bypassed to gain elevated (superuser) access, at some cost to built-in security guarantees", "Simply had its battery replaced", "Been factory reset with no other changes"], answer: 1, exp: "Rooting/jailbreaking unlocks deeper customization but can undermine sandboxing and other OS security protections." },
  { id: "mp-36", topic: "mobile-platforms", q: "Android's screen density buckets (mdpi/hdpi/xhdpi, etc.) are used to:", options: ["Determine the device's cellular carrier", "Scale UI assets (images, layouts) appropriately for different physical screen resolutions/densities", "Set the device's battery capacity", "Choose which apps can be installed"], answer: 1, exp: "This lets a single set of app resources look correctly sized across devices with very different pixel densities." },
  { id: "mp-37", topic: "mobile-platforms", q: "An 'Intent' in Android is:", options: ["A type of hardware sensor", "A messaging object used to request an action from another app component (e.g., launching an Activity)", "A cellular network protocol", "A file compression format"], answer: 1, exp: "Intents enable both intra-app navigation and inter-app communication (e.g., sharing content to another installed app)." },
  { id: "mp-38", topic: "mobile-platforms", q: "Push notifications rely on:", options: ["The app constantly polling the server while running in the foreground only", "A persistent connection/service (e.g., FCM or APNs) between the OS and a cloud service, delivering messages even when the app isn't actively running", "The user manually refreshing the app to check for updates", "SMS text messages exclusively"], answer: 1, exp: "This system-level channel lets the OS wake or notify the app without the app needing to stay running constantly." },
  { id: "mp-39", topic: "mobile-platforms", q: "A mobile platform's SDK (Software Development Kit) provides:", options: ["Only marketing materials for the platform", "The tools, libraries, and APIs developers need to build apps for that platform", "Only end-user documentation", "Only the app store listing page"], answer: 1, exp: "Examples include the Android SDK and the iOS SDK, bundled with their respective IDEs (Android Studio, Xcode)." },
  { id: "mp-40", topic: "mobile-platforms", q: "Compared to a smartphone, a feature phone is typically:", options: ["Capable of running any third-party app from an open ecosystem", "Limited mostly to calls/SMS/basic built-in apps, running proprietary firmware with no general-purpose app ecosystem", "Running the same OS as most smartphones", "Always more expensive than a smartphone"], answer: 1, exp: "The lack of an open app ecosystem is the key functional distinction from smartphones." },
  { id: "mp-41", topic: "mobile-platforms", q: "Process isolation on mobile OSes benefits users because:", options: ["It makes every app run slower", "A crash or misbehaving app is generally contained, protecting the overall system's stability", "It prevents any app from ever crashing", "It disables background notifications"], answer: 1, exp: "This isolation is closely related to app sandboxing's security and stability benefits." },
  { id: "mp-42", topic: "mobile-platforms", q: "A 'phablet' refers to:", options: ["A type of desktop computer", "A device blending phone and tablet form factors — a large-screen smartphone", "A cellular network standard", "A software development framework"], answer: 1, exp: "The term describes devices sized between typical phones and tablets." },
  { id: "mp-43", topic: "mobile-platforms", q: "A mobile 'launcher' app on Android provides:", options: ["The cellular modem firmware", "The home screen UI, app icons, and shortcuts — and can often be replaced by third-party launchers", "The device's Wi-Fi driver", "The app store's payment processing"], answer: 1, exp: "Android's relatively open platform allows swapping the default launcher for alternatives with different features/looks." },
  { id: "mp-44", topic: "mobile-platforms", q: "Compared to desktop computers, mobile hardware is generally characterized by:", options: ["Unlimited processing power and no battery constraints", "Less processing power, RAM, and storage, and being battery-constrained, requiring efficient software design", "Identical capabilities to high-end desktops in all cases", "No need for power management at all"], answer: 1, exp: "These constraints shape many mobile-specific software design and optimization practices." },
  { id: "mp-45", topic: "mobile-platforms", q: "A key reason developers often build native apps for both iOS and Android is to:", options: ["Avoid reaching any users at all", "Reach the largest possible user base across the two dominant mobile ecosystems", "Reduce their app to a single platform only", "Avoid using any SDK"], answer: 1, exp: "iOS and Android together account for the vast majority of the global smartphone market." },
  { id: "mp-46", topic: "mobile-platforms", q: "Over-the-air (OTA) updates for a mobile OS allow devices to:", options: ["Only be updated via a physical USB cable at an authorized store", "Download and install OS/software updates wirelessly without a physical connection", "Never receive any software updates", "Update only the device's hardware components"], answer: 1, exp: "OTA updates greatly simplify keeping a large, distributed fleet of devices current with security and feature updates." },
  { id: "mp-47", topic: "mobile-platforms", q: "The modem/baseband processor in a mobile SoC is responsible for:", options: ["Rendering the graphical user interface", "Handling cellular radio communication, separate from the main application processor", "Managing the touchscreen digitizer", "Running the app store"], answer: 1, exp: "Separating baseband processing from the application processor is a common mobile SoC design pattern." },
  { id: "mp-48", topic: "mobile-platforms", q: "A key difference in app distribution between Android and iOS is that Android:", options: ["Never allows any app installation at all", "Generally allows installing apps from outside the official store (sideloading APKs), while iOS largely restricts installation to the App Store", "Requires all apps to be pre-installed by the manufacturer", "Uses the exact same app store as iOS"], answer: 1, exp: "iOS's more locked-down distribution model is a deliberate part of Apple's closed-ecosystem approach." },
  { id: "mp-49", topic: "mobile-platforms", q: "Mobile platform version fragmentation impacts developers mainly by:", options: ["Eliminating the need for any testing", "Forcing them to support multiple OS versions/APIs simultaneously and test across a wide device matrix", "Guaranteeing identical behavior on every device automatically", "Removing the need for backward compatibility"], answer: 1, exp: "This is a particularly notable challenge in the more fragmented Android ecosystem." },
  { id: "mp-50", topic: "mobile-platforms", q: "Overall, understanding a mobile platform requires balancing:", options: ["Only the app's marketing budget", "Hardware capabilities, OS architecture/openness, app ecosystem, and device form factor against the target audience and app requirements", "Only the color scheme of the app icon", "Nothing beyond the programming language chosen"], answer: 1, exp: "These interconnected factors together shape platform choice and app design decisions." },

  // ================= Cellular Technologies (50) =================
  { id: "mc-01", topic: "mobile-cellular", q: "1G cellular networks were:", options: ["Fully digital, supporting high-speed data", "Analog, supporting primarily voice calls only, with no digital data/SMS services", "Based entirely on Wi-Fi technology", "The first networks to support 4K video streaming"], answer: 1, exp: "1G's analog nature limited it to basic voice service with no meaningful data capability." },
  { id: "mc-02", topic: "mobile-cellular", q: "2G cellular networks introduced:", options: ["Only analog voice calls, same as 1G", "Digital voice transmission plus basic data services like SMS", "5G-level data speeds", "The end of all cellular networks"], answer: 1, exp: "The shift from analog to digital in 2G also enabled features like SMS text messaging." },
  { id: "mc-03", topic: "mobile-cellular", q: "GSM stands for:", options: ["General Satellite Mobile", "Global System for Mobile Communications, a widely adopted 2G digital cellular standard", "Global Signal Modulation", "Ground Station Module"], answer: 1, exp: "GSM became the dominant 2G standard internationally, especially outside North America." },
  { id: "mc-04", topic: "mobile-cellular", q: "GSM primarily uses which multiple access technique?", options: ["Pure CDMA", "TDMA (Time Division Multiple Access), combined with FDMA for channelization", "OFDMA exclusively", "No multiple access technique at all"], answer: 1, exp: "TDMA divides each frequency channel into time slots, letting multiple users share it." },
  { id: "mc-05", topic: "mobile-cellular", q: "CDMA stands for:", options: ["Cellular Data Management Application", "Code Division Multiple Access, where users share the same frequency band simultaneously, distinguished by unique codes", "Central Distribution Mobile Antenna", "Cell Division Multiplexing Array"], answer: 1, exp: "CDMA's spread-spectrum approach lets many users transmit on the same frequencies at once." },
  { id: "mc-06", topic: "mobile-cellular", q: "A SIM card in GSM phones primarily stores:", options: ["The device's entire operating system", "Subscriber identity/authentication information, allowing the phone to be used across different GSM-compatible handsets", "The phone's camera photos", "The cellular tower's location data"], answer: 1, exp: "Because credentials live on the removable SIM, users can swap handsets while keeping their number/identity." },
  { id: "mc-07", topic: "mobile-cellular", q: "Traditional CDMA networks (unlike GSM) commonly identified subscribers via:", options: ["A removable SIM card, identical to GSM", "The device's ESN/MEID, rather than a removable SIM card", "A fingerprint scan", "A physical PIN pad on the tower"], answer: 1, exp: "Later CDMA/LTE devices did adopt SIM-like R-UIM/USIM cards, but classic CDMA (IS-95) was device-bound." },
  { id: "mc-08", topic: "mobile-cellular", q: "GPRS (General Packet Radio Service), sometimes called '2.5G', added:", options: ["Only faster voice calls", "Packet-switched data capability on top of GSM's circuit-switched voice network", "5G speeds to GSM networks", "A replacement for SIM cards"], answer: 1, exp: "GPRS was an early step toward mobile internet data services, before later EDGE and 3G improvements." },
  { id: "mc-09", topic: "mobile-cellular", q: "EDGE (Enhanced Data rates for GSM Evolution), sometimes called '2.75G':", options: ["Removed all data capability from GSM", "Further improved GSM data speeds beyond GPRS, as a stepping stone toward 3G", "Was a 5G technology", "Only worked with CDMA networks"], answer: 1, exp: "EDGE offered meaningfully faster data than GPRS while still building on GSM infrastructure." },
  { id: "mc-10", topic: "mobile-cellular", q: "3G cellular networks primarily improved:", options: ["Only voice call clarity, with no data changes", "Data transfer speeds, enabling mobile internet, video calling, and richer multimedia", "Battery life exclusively", "Only SMS text delivery speed"], answer: 1, exp: "3G's higher throughput made practical mobile internet browsing possible for the first time." },
  { id: "mc-11", topic: "mobile-cellular", q: "UMTS (Universal Mobile Telecommunications System) is:", options: ["A 1G analog standard", "A 3G standard in the GSM lineage, using W-CDMA as its air interface", "A Wi-Fi standard", "A satellite-only technology"], answer: 1, exp: "UMTS represents the GSM ecosystem's evolution into 3G." },
  { id: "mc-12", topic: "mobile-cellular", q: "CDMA2000 is:", options: ["A 4G LTE standard", "A 3G standard in the CDMA lineage, evolving from earlier IS-95 CDMA networks", "A Wi-Fi protocol", "A type of SIM card"], answer: 1, exp: "CDMA2000 represents the CDMA ecosystem's evolution into 3G, parallel to UMTS in the GSM lineage." },
  { id: "mc-13", topic: "mobile-cellular", q: "HSPA (High Speed Packet Access), sometimes called '3.5G':", options: ["Was a downgrade from basic 3G", "Enhanced UMTS/3G networks with higher data throughput", "Replaced GSM entirely with a new radio technology", "Only worked with 2G phones"], answer: 1, exp: "HSPA improved 3G data speeds without requiring a full generational leap to 4G." },
  { id: "mc-14", topic: "mobile-cellular", q: "4G cellular networks are primarily defined by:", options: ["A return to analog transmission", "LTE (Long Term Evolution) technology, offering an all-IP architecture and much higher data speeds than 3G", "GSM's original 2G design", "The elimination of cellular towers"], answer: 1, exp: "LTE's all-IP design and higher bandwidth marked a significant architectural shift from earlier generations." },
  { id: "mc-15", topic: "mobile-cellular", q: "LTE's downlink (network-to-device) commonly uses which multiple access scheme?", options: ["Pure TDMA", "OFDMA (Orthogonal Frequency Division Multiple Access)", "Analog FM modulation", "No multiple access scheme"], answer: 1, exp: "OFDMA efficiently divides bandwidth among users using orthogonal subcarriers, well suited to high-speed downlink data." },
  { id: "mc-16", topic: "mobile-cellular", q: "LTE's uplink (device-to-network) commonly uses which scheme, chosen partly to reduce handset power consumption?", options: ["OFDMA, same as the downlink", "SC-FDMA (Single Carrier Frequency Division Multiple Access)", "Analog AM modulation", "Pure CDMA"], answer: 1, exp: "SC-FDMA has a lower peak-to-average power ratio than OFDMA, helping conserve battery on the transmitting device." },
  { id: "mc-17", topic: "mobile-cellular", q: "VoLTE (Voice over LTE) enables:", options: ["Voice calls to fall back to older 2G circuit-switched networks exclusively", "Voice calls to be carried as data packets over the all-IP LTE network, instead of relying on older circuit-switched voice", "Only video calls, never audio-only calls", "Cellular networks to disable voice entirely"], answer: 1, exp: "VoLTE lets carriers offer voice service natively over the same packet-based LTE network used for data." },
  { id: "mc-18", topic: "mobile-cellular", q: "The Evolved Packet Core (EPC) in LTE networks is:", options: ["A type of physical SIM card", "The all-IP core network architecture that replaced the older circuit-switched core used in 2G/3G", "A cellular tower's antenna array", "A mobile app development framework"], answer: 1, exp: "EPC's flatter, all-IP design supports LTE's higher performance and VoLTE." },
  { id: "mc-19", topic: "mobile-cellular", q: "A 'cell' in cellular network design refers to:", options: ["A single subscriber's phone", "A geographic coverage area served by one base station, allowing frequency reuse across non-adjacent cells", "A type of SIM card", "The network's core switching center"], answer: 1, exp: "Dividing coverage into cells is the foundational idea that gives 'cellular' networks their name." },
  { id: "mc-20", topic: "mobile-cellular", q: "Frequency reuse in cellular networks allows:", options: ["Only one cell in the entire network to use any frequency", "The same frequency channels to be reused in different, sufficiently separated cells, increasing overall network capacity", "All cells to share one single unlicensed frequency", "Frequencies to be permanently retired after one use"], answer: 1, exp: "Careful spatial separation between cells using the same frequencies avoids excessive interference." },
  { id: "mc-21", topic: "mobile-cellular", q: "A handoff/handover in a cellular network occurs when:", options: ["A subscriber cancels their service", "A mobile device's active connection is transferred from one cell/base station to another as the user moves", "A SIM card is physically swapped", "A device is powered off"], answer: 1, exp: "Seamless handoffs are essential for maintaining calls/data sessions as users move between cell coverage areas." },
  { id: "mc-22", topic: "mobile-cellular", q: "A BTS (Base Transceiver Station) in a GSM network is responsible for:", options: ["Billing subscribers", "Direct radio communication with mobile devices within its cell", "Storing subscriber contact lists", "Manufacturing SIM cards"], answer: 1, exp: "The BTS is the radio equipment closest to the mobile device, forming the air interface." },
  { id: "mc-23", topic: "mobile-cellular", q: "A BSC (Base Station Controller) in a GSM network:", options: ["Directly transmits radio signals to phones", "Manages multiple BTSs, handling functions like handover and radio resource allocation", "Is a type of subscriber's mobile device", "Only exists in 4G LTE networks"], answer: 1, exp: "The BSC coordinates several BTSs, sitting between them and the core network switching center." },
  { id: "mc-24", topic: "mobile-cellular", q: "An MSC (Mobile Switching Center):", options: ["Only stores subscriber contact information", "Switches calls between mobile users and other networks (PSTN, other mobile networks), a core circuit-switching component", "Is a type of touchscreen technology", "Only exists in Wi-Fi networks"], answer: 1, exp: "The MSC is central to routing voice calls in traditional circuit-switched cellular architectures." },
  { id: "mc-25", topic: "mobile-cellular", q: "The HLR (Home Location Register) stores:", options: ["Only temporary visitor information", "Permanent subscriber information (like IMSI details and subscribed services) for a network's own subscribers", "The device's app store purchase history", "Cellular tower maintenance logs"], answer: 1, exp: "The HLR is the authoritative, permanent record for a carrier's own subscribers." },
  { id: "mc-26", topic: "mobile-cellular", q: "The VLR (Visitor Location Register) temporarily stores:", options: ["A subscriber's permanent home-network profile only", "Information about subscribers currently located in (visiting) a particular MSC's service area, including roaming subscribers", "The device's installed apps", "Software updates for the base station"], answer: 1, exp: "The VLR supports mobility by tracking subscribers temporarily present in a given area, including roamers." },
  { id: "mc-27", topic: "mobile-cellular", q: "Roaming in cellular networks allows:", options: ["A subscriber to use their phone only within their home carrier's exact coverage area", "A subscriber to use their phone on a different (often partner) network, typically outside their home carrier's coverage", "Devices to switch operating systems automatically", "SIM cards to be permanently disabled"], answer: 1, exp: "Roaming agreements between carriers let subscribers maintain service while traveling." },
  { id: "mc-28", topic: "mobile-cellular", q: "FDMA (Frequency Division Multiple Access) lets multiple users share a channel by:", options: ["Assigning each user a distinct time slot", "Assigning each user a distinct frequency sub-band", "Assigning each user a unique spreading code", "Giving every user the exact same frequency and time slot simultaneously"], answer: 1, exp: "FDMA was foundational to early 1G analog systems and remains a building block in later hybrid schemes." },
  { id: "mc-29", topic: "mobile-cellular", q: "TDMA (Time Division Multiple Access) lets multiple users share a channel by:", options: ["Assigning each user a distinct frequency", "Assigning each user a distinct time slot on the same frequency", "Assigning each user a unique spreading code", "Requiring all users to transmit simultaneously with no separation"], answer: 1, exp: "GSM's use of TDMA lets several users take turns transmitting on the same frequency channel." },
  { id: "mc-30", topic: "mobile-cellular", q: "CDMA's spread-spectrum approach lets multiple users share a channel by:", options: ["Assigning each user a distinct time slot only", "Assigning each user a unique code, letting all users transmit simultaneously on the same frequency band and be distinguished by their code", "Assigning each user a distinct frequency only", "Prohibiting more than one user from transmitting at all"], answer: 1, exp: "This code-based separation is what distinguishes CDMA from the time- or frequency-based separation of TDMA/FDMA." },
  { id: "mc-31", topic: "mobile-cellular", q: "A key theoretical advantage sometimes cited for CDMA over strict TDMA/FDMA is:", options: ["A hard, fixed capacity limit with no flexibility", "A 'softer' capacity limit (graceful degradation) since it doesn't strictly divide the channel into fixed time/frequency slots", "Requiring no spectrum allocation at all", "Being incompatible with any base station infrastructure"], answer: 1, exp: "As more CDMA users are added, interference gradually increases rather than abruptly running out of fixed slots." },
  { id: "mc-32", topic: "mobile-cellular", q: "The IMSI (International Mobile Subscriber Identity) is:", options: ["A number identifying the physical handset", "A unique number identifying a subscriber, stored on the SIM card, used for network authentication", "The device's Wi-Fi MAC address", "A cellular tower's identifier"], answer: 1, exp: "The IMSI is tied to the subscriber's account/SIM, not the physical device." },
  { id: "mc-33", topic: "mobile-cellular", q: "The IMEI (International Mobile Equipment Identity) identifies:", options: ["The subscriber's account", "The physical mobile device/handset itself, distinct from the subscriber identity (IMSI)", "The cellular carrier's billing address", "The SIM card's manufacturer"], answer: 1, exp: "IMEI is commonly used to identify/block stolen devices, independent of whichever SIM is inserted." },
  { id: "mc-34", topic: "mobile-cellular", q: "Cellular network 'cell splitting' is used to:", options: ["Reduce the total number of subscribers a network can serve", "Increase network capacity in high-demand areas by dividing a large cell into several smaller cells, each with its own base station", "Permanently disable a cell tower", "Merge multiple carriers into a single network"], answer: 1, exp: "Smaller cells allow more aggressive frequency reuse, boosting capacity in dense urban areas." },
  { id: "mc-35", topic: "mobile-cellular", q: "A soft handoff (used in CDMA networks), compared to a hard handoff (typical in GSM), means:", options: ["The connection is always dropped briefly during handoff", "The device briefly maintains simultaneous connections to more than one base station during the transition, reducing dropped-call risk", "No handoff occurs at all in CDMA", "The device must be restarted"], answer: 1, exp: "This overlap-based approach is a natural fit for CDMA's ability to distinguish signals by code even from multiple base stations at once." },
  { id: "mc-36", topic: "mobile-cellular", q: "3G's key improvement supporting mobile video calling and richer internet browsing was:", options: ["A return to analog transmission", "Significantly higher data throughput compared to 2G/2.5G networks", "The removal of SIM cards", "Elimination of cellular towers"], answer: 1, exp: "Higher bandwidth was the essential enabler for these richer, more data-intensive mobile services." },
  { id: "mc-37", topic: "mobile-cellular", q: "A key motivation for shifting from circuit-switched to all-IP (packet-switched) cellular core networks, as in LTE, was:", options: ["IP networks being inherently less efficient", "Better efficiency and flexibility for carrying data traffic (including voice as data via VoLTE), matching how the wider internet operates", "Eliminating the need for any core network at all", "Making voice calls impossible"], answer: 1, exp: "Unifying voice and data onto one packet-switched architecture simplified and modernized cellular core networks." },
  { id: "mc-38", topic: "mobile-cellular", q: "Before GPRS, data services on GSM networks (if used at all) mainly relied on:", options: ["An always-on high-speed packet connection", "Circuit-switched data connections, conceptually similar to a dial-up modem call", "5G network slicing", "Satellite-only connectivity"], answer: 1, exp: "This circuit-switched approach was inefficient for bursty data traffic, motivating GPRS's packet-switched design." },
  { id: "mc-39", topic: "mobile-cellular", q: "The trade-off between cellular 'coverage area' and 'capacity' means:", options: ["There is no trade-off; both can always be maximized freely", "Fewer, larger cells maximize coverage area but support fewer simultaneous users; more, smaller cells increase capacity but require more infrastructure", "Coverage area and capacity are unrelated concepts", "Capacity always decreases as cell size decreases"], answer: 1, exp: "Network planners balance this trade-off differently for rural (larger cells) versus dense urban (smaller cells) deployments." },
  { id: "mc-40", topic: "mobile-cellular", q: "The fully ITU-compliant successor standard sometimes distinguished from early marketed '4G' LTE is often called:", options: ["3G Plus", "LTE-Advanced", "GSM Evolution", "5G NR"], answer: 1, exp: "Early LTE deployments were marketed as '4G' even before fully meeting the ITU's original technical requirements; LTE-Advanced later met them more fully." },
  { id: "mc-41", topic: "mobile-cellular", q: "A key reason GSM became the dominant global 2G standard was:", options: ["It required no SIM card at all", "Its widespread international adoption and standardized SIM-based roaming, unlike the more regionally fragmented deployment of CDMA (IS-95)", "It was the only standard capable of voice calls", "It was developed after CDMA and 3G"], answer: 1, exp: "GSM's international standardization and SIM-based portability supported broad global interoperability and roaming." },
  { id: "mc-42", topic: "mobile-cellular", q: "Cellular frequency bands are licensed/allocated by:", options: ["Individual device manufacturers", "Government regulatory bodies, since radio spectrum is a finite, shared public resource", "App store operators", "Cellular subscribers themselves"], answer: 1, exp: "Spectrum licensing prevents chaotic interference between competing users of the same frequencies." },
  { id: "mc-43", topic: "mobile-cellular", q: "A 'dead zone' (area of poor cellular coverage) typically results from:", options: ["Too many available frequencies", "Insufficient base station density or physical obstructions (terrain, buildings) blocking radio signals", "An oversupply of cell towers", "Excessive SIM card capacity"], answer: 1, exp: "Filling coverage gaps generally requires adding more base stations or repeaters in the affected area." },
  { id: "mc-44", topic: "mobile-cellular", q: "Which cellular generation first enabled practical mobile internet browsing at meaningful speeds?", options: ["1G", "2G", "3G", "None — mobile internet requires Wi-Fi"], answer: 2, exp: "3G's substantial data-speed improvements over 2G/2.5G made mobile web browsing genuinely usable." },
  { id: "mc-45", topic: "mobile-cellular", q: "The primary user-facing benefit driving adoption of 4G/LTE over 3G was:", options: ["Lower audio quality on voice calls", "Substantially higher data speeds and lower latency, better supporting streaming video, app-heavy usage, and VoLTE", "The removal of mobile internet access", "Mandatory downgrade of smartphone features"], answer: 1, exp: "These performance gains directly enabled richer app experiences and better multimedia streaming." },
  { id: "mc-46", topic: "mobile-cellular", q: "A dual-mode or multi-band cellular device supports:", options: ["Only a single fixed frequency band forever", "Operating across multiple frequency bands and/or multiple network technologies, useful for international roaming/compatibility", "Only Wi-Fi, never cellular", "Only 1G analog networks"], answer: 1, exp: "Multi-band/multi-mode support lets a single device work across different carriers' networks and regions." },
  { id: "mc-47", topic: "mobile-cellular", q: "'Cell breathing' in CDMA networks refers to:", options: ["A cell physically changing its geographic location", "A cell's effective coverage area shrinking under high user load (more interference) and expanding under low load", "A type of hardware failure", "A cellular tower literally inflating and deflating"], answer: 1, exp: "This dynamic coverage effect is a consequence of CDMA's interference-limited (rather than strictly slot-limited) capacity model." },
  { id: "mc-48", topic: "mobile-cellular", q: "A key architectural shift enabling 4G LTE's higher performance compared to 3G was:", options: ["Adding more circuit-switched network elements", "A flatter, simplified all-IP network architecture reducing the number of network elements data must pass through", "Removing all base stations", "Reverting to analog transmission"], answer: 1, exp: "This architectural simplification reduced latency and improved efficiency compared to older, more layered 3G/2G core networks." },
  { id: "mc-49", topic: "mobile-cellular", q: "GSM's use of a removable SIM card (compared to earlier device-bound identification) primarily benefited users by:", options: ["Making it impossible to ever change phones", "Letting them easily switch phones while keeping their subscriber identity/number, since credentials live on the removable SIM", "Eliminating the need for any subscriber authentication", "Requiring a new phone number every time the SIM is moved"], answer: 1, exp: "This portability was a notable usability improvement over systems that tied identity directly to a specific device." },
  { id: "mc-50", topic: "mobile-cellular", q: "Overall, the progression from 1G through 4G cellular technologies reflects a shift from:", options: ["Digital, high-speed networks toward analog, voice-only networks", "Analog, voice-only communication toward digital, increasingly high-speed, all-IP data-centric mobile networks", "Wired telephony toward no telephony at all", "A single unchanging technology across all generations"], answer: 1, exp: "Each generation built on the last, progressively adding digital transmission, data capability, and higher throughput/lower latency all-IP architectures." },

  // ================= Mobile App Development (50) =================
  { id: "ad-01", topic: "mobile-appdev", q: "A native mobile app is built using:", options: ["Only generic web technologies with no platform SDK", "The platform's own SDK and programming language (e.g., Kotlin/Java for Android, Swift/Objective-C for iOS), giving full access to platform APIs and best performance", "A single codebase that cannot access any device hardware", "Only server-side code with no client component"], answer: 1, exp: "Native development typically offers the best performance and deepest platform integration, at the cost of maintaining separate codebases per platform." },
  { id: "ad-02", topic: "mobile-appdev", q: "A hybrid mobile app is typically built by:", options: ["Compiling directly to each platform's native machine code with no web technology involved", "Wrapping a web-based UI (HTML/CSS/JS) inside a native container/WebView, allowing a largely shared codebase across platforms", "Running exclusively inside a desktop browser", "Requiring a completely separate app for every screen size"], answer: 1, exp: "Frameworks like Cordova/PhoneGap popularized this wrap-a-webview approach to cross-platform development." },
  { id: "ad-03", topic: "mobile-appdev", q: "A cross-platform framework like React Native or Flutter allows developers to:", options: ["Write completely separate code for each platform with no sharing", "Write app code largely once and deploy to multiple platforms, while still rendering natively (or near-natively) on each", "Only build web pages, never installable apps", "Avoid using any programming language"], answer: 1, exp: "These frameworks aim to combine much of native performance/feel with the development efficiency of a shared codebase." },
  { id: "ad-04", topic: "mobile-appdev", q: "A Progressive Web App (PWA) is:", options: ["A native app that cannot run in any browser", "A web application built to behave like a native app (offline support, installability, push notifications) while running through browser/web technologies", "Only usable on desktop computers", "A type of cellular technology"], answer: 1, exp: "PWAs blur the line between traditional websites and installed native apps." },
  { id: "ad-05", topic: "mobile-appdev", q: "A key advantage of native app development over hybrid/cross-platform approaches is typically:", options: ["Guaranteed lower development cost", "Best achievable performance and fullest access to platform-specific APIs and hardware features", "Automatically working identically across all platforms with zero extra code", "Eliminating the need for any testing"], answer: 1, exp: "This performance/API-access advantage is the main trade-off against native development's higher per-platform cost." },
  { id: "ad-06", topic: "mobile-appdev", q: "A key advantage of hybrid/cross-platform development over fully native development is typically:", options: ["Always superior raw performance to native apps", "A largely shared codebase across platforms, reducing development time/cost compared to maintaining separate native codebases", "Guaranteed access to every platform-specific hardware feature immediately", "Eliminating the need for any platform SDK"], answer: 1, exp: "Shared code can significantly cut development and maintenance effort compared to fully separate native codebases." },
  { id: "ad-07", topic: "mobile-appdev", q: "Android Studio is:", options: ["Apple's IDE for iOS development", "The official Integrated Development Environment (IDE) for building native Android applications", "A cloud hosting service", "A cellular network simulator only"], answer: 1, exp: "Android Studio is built on IntelliJ IDEA and is Google's officially supported Android development environment." },
  { id: "ad-08", topic: "mobile-appdev", q: "Xcode is:", options: ["Google's Android development IDE", "Apple's official IDE, used for developing native iOS (and macOS) applications, primarily in Swift or Objective-C", "A cross-platform web framework", "A cellular carrier's billing system"], answer: 1, exp: "Xcode includes tools for coding, debugging, interface design, and the iOS Simulator." },
  { id: "ad-09", topic: "mobile-appdev", q: "An emulator/simulator used during mobile app development is used to:", options: ["Permanently replace the need for any physical device testing", "Test an app on a virtual device without needing physical hardware, though some behaviors are best verified on real devices", "Only test the app's network connectivity", "Automatically publish the app to the store"], answer: 1, exp: "Emulators are convenient for rapid iteration, but real devices remain important for verifying sensors, real-world performance, and hardware quirks." },
  { id: "ad-10", topic: "mobile-appdev", q: "The MVC (Model-View-Controller) architecture pattern separates an app into:", options: ["A single undivided block of code", "Data/business logic (Model), UI presentation (View), and the logic connecting them (Controller)", "Only front-end and back-end, with no further separation", "Model, Version, Container"], answer: 1, exp: "MVC's separation of concerns helps keep UI code, business logic, and data handling more maintainable and testable." },
  { id: "ad-11", topic: "mobile-appdev", q: "The MVVM (Model-View-ViewModel) pattern, popular in modern mobile app architectures, adds a:", options: ["Database layer with no UI connection", "ViewModel layer that exposes data/state to the View in an observable way, helping separate UI logic from business logic", "Layer that eliminates the need for any Model", "Networking layer only"], answer: 1, exp: "MVVM is particularly well suited to frameworks with reactive/data-binding UI systems." },
  { id: "ad-12", topic: "mobile-appdev", q: "A mobile app typically communicates with a remote backend server via:", options: ["Only direct database file access", "REST (or similar) APIs over HTTP(S), exchanging data usually in JSON format", "Bluetooth exclusively", "Physical USB connection only"], answer: 1, exp: "REST-over-HTTP(S) with JSON is the most common pattern for mobile app-to-backend communication." },
  { id: "ad-13", topic: "mobile-appdev", q: "SQLite is commonly used in mobile app development as:", options: ["A cloud-only database with no local option", "A lightweight, embedded relational database for local, on-device data storage", "A cellular network protocol", "A UI design framework"], answer: 1, exp: "SQLite's small footprint and embeddability make it well suited for local mobile app storage needs." },
  { id: "ad-14", topic: "mobile-appdev", q: "'Offline-first' app design means:", options: ["The app only works when connected to the internet", "The app is built to remain functional (at least partially) without a network connection, syncing data once connectivity is restored", "The app deletes all local data automatically", "The app requires a permanent Wi-Fi connection at all times"], answer: 1, exp: "This is important for mobile apps given cellular/Wi-Fi connectivity's frequent unreliability." },
  { id: "ad-15", topic: "mobile-appdev", q: "Deep linking in a mobile app allows:", options: ["A link to always just open the device's home screen", "A URL or link to open the app directly to a specific screen/content, rather than just launching the app to its default screen", "The app to permanently disable navigation", "Only external websites to be opened, never the app itself"], answer: 1, exp: "Deep links are commonly used in notifications, marketing campaigns, and shared content to jump straight to relevant app content." },
  { id: "ad-16", topic: "mobile-appdev", q: "In-app purchases (IAP) allow:", options: ["Only free content to ever be accessed", "Users to buy digital goods, subscriptions, or premium features directly within the app, typically processed through the platform's payment system", "Physical goods to be shipped directly through the OS", "Apps to bypass all payment processing entirely"], answer: 1, exp: "Platform-provided IAP systems (App Store, Play Store billing) handle payment processing and often take a revenue share." },
  { id: "ad-17", topic: "mobile-appdev", q: "An Android APK (or iOS IPA) file is:", options: ["A type of database file", "The packaged, installable application file distributed to devices or app stores", "A network configuration file", "A cellular SIM profile"], answer: 1, exp: "These are the built, distributable artifact formats for Android and iOS apps respectively." },
  { id: "ad-18", topic: "mobile-appdev", q: "App versioning (e.g., semantic versioning) is important for:", options: ["Nothing meaningful — version numbers are purely cosmetic", "Tracking releases, managing updates, and helping developers/users understand the scope of changes between versions", "Preventing any future updates from being released", "Replacing the need for a changelog"], answer: 1, exp: "Consistent versioning helps coordinate releases, dependency management, and communicate change scope." },
  { id: "ad-19", topic: "mobile-appdev", q: "Unit testing in mobile app development focuses on:", options: ["Testing the entire app's UI end-to-end", "Verifying individual functions/components of the app's code work correctly in isolation", "Testing only the network layer", "Testing only on physical devices, never emulators"], answer: 1, exp: "Unit tests isolate small pieces of logic, making failures easier to pinpoint and fix." },
  { id: "ad-20", topic: "mobile-appdev", q: "UI/instrumentation testing in mobile app development focuses on:", options: ["Only testing backend server code", "Verifying the app's user interface behaves correctly through simulated user interactions, often on an emulator or device", "Testing the app's app-store listing text", "Testing only the app icon's design"], answer: 1, exp: "UI tests exercise the app much as a real user would, clicking through screens and verifying results." },
  { id: "ad-21", topic: "mobile-appdev", q: "A key reason to test on real physical devices (not just emulators/simulators) is to:", options: ["Emulators always perfectly replicate every real-world condition", "Catch real-world performance, hardware-sensor, and device-fragmentation issues that emulators may not fully replicate", "Avoid needing any automated tests", "Guarantee zero bugs before release"], answer: 1, exp: "Real devices can reveal issues (e.g., with specific sensors, chipsets, or manufacturers) that emulators may not surface." },
  { id: "ad-22", topic: "mobile-appdev", q: "App store submission guidelines (e.g., Apple's App Review Guidelines) exist to:", options: ["Guarantee every app is approved instantly with no review", "Ensure apps meet quality, security, content, and functionality standards before being made available to users", "Prevent any apps from ever being published", "Only apply to free apps, never paid ones"], answer: 1, exp: "Review processes aim to protect users from broken, malicious, or policy-violating apps." },
  { id: "ad-23", topic: "mobile-appdev", q: "A common reason for app store rejection is:", options: ["The app having too few downloads", "Violating platform guidelines (e.g., crashes, misleading functionality, privacy violations, disallowed content)", "The app being written in the officially recommended language", "The developer having too many other published apps"], answer: 1, exp: "Reviewers specifically check for policy compliance, stability, and honest representation of app functionality." },
  { id: "ad-24", topic: "mobile-appdev", q: "Mobile app performance optimization commonly targets:", options: ["Maximizing background CPU usage regardless of impact", "Reducing battery drain, memory usage, and unnecessary network calls, given mobile devices' constrained resources", "Increasing app size without limit", "Ignoring resource usage entirely"], answer: 1, exp: "These optimizations directly affect user experience (responsiveness, battery life) on resource-constrained mobile hardware." },
  { id: "ad-25", topic: "mobile-appdev", q: "Lazy loading, as an app development technique, means:", options: ["Loading every resource immediately at app launch regardless of need", "Deferring the loading of resources (images, data, screens) until they are actually needed, improving initial load time and resource usage", "Never loading any resources at all", "Loading resources in a random, unpredictable order"], answer: 1, exp: "Lazy loading helps apps start faster and use memory/network more efficiently." },
  { id: "ad-26", topic: "mobile-appdev", q: "Caching data locally on a mobile device helps:", options: ["Increase redundant network requests", "Reduce redundant network requests and improve perceived performance/offline capability", "Guarantee data is always perfectly up to date with no risk of staleness", "Eliminate the need for any backend server"], answer: 1, exp: "Local caching trades some risk of stale data for improved speed and resilience to connectivity issues." },
  { id: "ad-27", topic: "mobile-appdev", q: "A RESTful API's standard HTTP methods (GET, POST, PUT, DELETE), in a mobile app-backend context, correspond respectively to:", options: ["Deleting, creating, retrieving, and updating resources", "Retrieving, creating, updating, and deleting resources on the server", "Only reading data, with no other operations possible", "Formatting the device's local storage"], answer: 1, exp: "This conventional mapping helps keep API design consistent and predictable across mobile app-backend integrations." },
  { id: "ad-28", topic: "mobile-appdev", q: "JSON (JavaScript Object Notation) is commonly used in mobile app development for:", options: ["Compiling native binary code", "A lightweight, human-readable data-interchange format between the app and backend APIs", "Storing the app's compiled machine code", "Rendering the app's UI directly"], answer: 1, exp: "JSON's simplicity and wide language support make it a very common choice for mobile API payloads." },
  { id: "ad-29", topic: "mobile-appdev", q: "Push notification services (e.g., Firebase Cloud Messaging, Apple Push Notification service) allow a backend to:", options: ["Only communicate with an app while it's actively open in the foreground", "Send timely messages/alerts to an app even when it isn't actively running in the foreground", "Directly modify the app's installed code", "Bypass the need for any network connection"], answer: 1, exp: "These platform-level push services maintain a persistent channel so alerts can reach devices promptly." },
  { id: "ad-30", topic: "mobile-appdev", q: "Requesting runtime permissions (e.g., camera, location) at the point of use, rather than all upfront at install, is considered good practice because:", options: ["It hides the reason for needing the permission from the user", "It gives users clearer context for why a permission is needed, improving trust and reducing unnecessary permission denials", "It removes the user's ability to deny the permission", "It is required by law in every country"], answer: 1, exp: "Contextual permission requests generally lead to better user understanding and higher grant rates." },
  { id: "ad-31", topic: "mobile-appdev", q: "An app's 'onboarding' flow refers to:", options: ["The process of uninstalling the app", "The initial screens/tutorial shown to new users to introduce the app's key features and guide setup", "A backend server configuration step", "A type of automated testing"], answer: 1, exp: "Good onboarding helps new users quickly understand and start getting value from the app." },
  { id: "ad-32", topic: "mobile-appdev", q: "Continuous Integration/Continuous Deployment (CI/CD), applied to mobile app development, helps:", options: ["Manually build and test each release by hand every time", "Automate building, testing, and (optionally) distributing new app versions on every code change", "Eliminate the need for any version control", "Guarantee the app never has any bugs"], answer: 1, exp: "CI/CD reduces manual effort and catches integration issues earlier through automated pipelines." },
  { id: "ad-33", topic: "mobile-appdev", q: "A/B testing in mobile app development is used to:", options: ["Test only for crashes, nothing else", "Compare two variants of a feature/design with different user segments to determine which performs better against a defined metric", "Guarantee both variants perform identically", "Replace the need for any analytics"], answer: 1, exp: "A/B testing provides data-driven evidence for design/feature decisions rather than relying purely on intuition." },
  { id: "ad-34", topic: "mobile-appdev", q: "Crash reporting/analytics tools (e.g., Firebase Crashlytics) in production mobile apps help developers:", options: ["Prevent all crashes from ever occurring automatically", "Automatically detect, log, and diagnose app crashes experienced by real users in the field", "Only work during local development, never in production", "Replace the need for any manual testing before release"], answer: 1, exp: "These tools give visibility into real-world crash patterns that internal testing alone might miss." },
  { id: "ad-35", topic: "mobile-appdev", q: "A key reason to design mobile apps with a responsive/adaptive layout is:", options: ["All mobile devices have identical screen sizes", "Devices vary widely in screen size and resolution, so a single fixed layout would not display well across all of them", "Fixed layouts always look best on every device", "Responsive design is only relevant to desktop websites"], answer: 1, exp: "Given the enormous variety of device screens, flexible layouts are essential for consistent usability." },
  { id: "ad-36", topic: "mobile-appdev", q: "Background services/tasks in mobile OSes are often restricted (e.g., limited execution time, batching) mainly to:", options: ["Make apps run faster in the foreground only", "Conserve battery life and system resources, since unrestricted background activity would drain the device quickly", "Prevent any app from ever running at all", "Increase network usage deliberately"], answer: 1, exp: "OS-level restrictions on background work are a direct response to mobile devices' battery/resource constraints." },
  { id: "ad-37", topic: "mobile-appdev", q: "A 'freemium' mobile app monetization model means:", options: ["The app requires payment before any download is possible", "The app is free to download and use with basic features, while charging for premium features or content via in-app purchases/subscriptions", "The app can never generate any revenue", "All features are always completely free with no paid options"], answer: 1, exp: "Freemium is one of the most common mobile monetization strategies, lowering the barrier to initial adoption." },
  { id: "ad-38", topic: "mobile-appdev", q: "Localization of a mobile app involves:", options: ["Only translating the app's name", "Adapting the app's text, formats (dates, currency), and sometimes layout/content for different languages and regions", "Removing all text from the app entirely", "Only applies to the app icon's design"], answer: 1, exp: "Good localization goes beyond simple translation to also handle formatting and cultural conventions." },
  { id: "ad-39", topic: "mobile-appdev", q: "An app's manifest file (e.g., AndroidManifest.xml, iOS Info.plist) declares:", options: ["The app's entire source code", "Essential app metadata such as permissions required, components (activities/screens), and configuration the OS needs before running the app", "Only the app's marketing description", "The user's personal data"], answer: 1, exp: "The OS reads this manifest to understand how to install, launch, and grant permissions to the app." },
  { id: "ad-40", topic: "mobile-appdev", q: "A key benefit of using a cross-platform framework's 'hot reload' feature during development is:", options: ["It permanently disables debugging", "Seeing code changes reflected almost instantly in the running app without a full rebuild, speeding up the development cycle", "It automatically publishes the app to the store", "It replaces the need for any testing"], answer: 1, exp: "Hot reload significantly speeds up the iterative edit-test cycle common in UI-heavy development." },
  { id: "ad-41", topic: "mobile-appdev", q: "The mobile app security practice of not storing sensitive data (like passwords) in plain text locally is important because:", options: ["Plain text storage is always the fastest option with no downside", "A lost/stolen or compromised device could otherwise expose that sensitive data directly", "Local storage is never accessible to anyone", "Encryption is illegal on mobile devices"], answer: 1, exp: "Encrypting or avoiding storage of sensitive data locally limits exposure if a device is lost or compromised." },
  { id: "ad-42", topic: "mobile-appdev", q: "An app's 'splash screen' serves to:", options: ["Permanently block the user from using the app", "Display briefly while the app initializes/loads, providing visual feedback rather than a blank screen", "Replace the need for an app icon", "Only appear after the app has fully loaded"], answer: 1, exp: "A brief splash screen improves perceived responsiveness during unavoidable startup delay." },
  { id: "ad-43", topic: "mobile-appdev", q: "Cordova/PhoneGap-style hybrid frameworks bridge web code to native device features via:", options: ["Direct compilation of JavaScript into native machine code", "Plugins that expose native APIs (camera, GPS, etc.) to the JavaScript running inside the WebView", "Requiring the developer to rewrite the entire app in native code", "A cellular network protocol"], answer: 1, exp: "Plugins are the mechanism that lets otherwise web-based code access device hardware capabilities." },
  { id: "ad-44", topic: "mobile-appdev", q: "A key challenge specific to cross-platform frameworks is:", options: ["They never require any platform-specific code", "Occasionally needing platform-specific code or plugins for features not fully supported by the shared framework, and potential performance overhead versus fully native code", "They cannot access any device hardware at all", "They are always faster than fully native apps"], answer: 1, exp: "Despite broad code sharing, edge cases and performance-critical features sometimes still need platform-specific handling." },
  { id: "ad-45", topic: "mobile-appdev", q: "Beta testing (e.g., via TestFlight for iOS or Google Play's testing tracks) before a full public release allows developers to:", options: ["Skip all future testing permanently", "Gather real-user feedback and catch issues on a limited audience before wider release", "Guarantee the app store will approve the app instantly", "Avoid needing any crash reporting"], answer: 1, exp: "Beta programs provide a controlled way to validate an app with real users before a broader launch." },
  { id: "ad-46", topic: "mobile-appdev", q: "A mobile app's network layer typically implements retry/timeout logic mainly because:", options: ["Mobile network connections are always perfectly stable", "Mobile network connectivity (cellular/Wi-Fi) is often intermittent or variable, unlike a typically stable wired connection", "Retries are required by every app store's policy", "Timeouts are purely cosmetic with no functional purpose"], answer: 1, exp: "Robust handling of connectivity fluctuations is essential given how variable mobile networks can be." },
  { id: "ad-47", topic: "mobile-appdev", q: "State management libraries/patterns (e.g., Redux-style patterns or platform-native equivalents) in app development help:", options: ["Eliminate the need for any UI at all", "Manage and synchronize an app's data/UI state consistently as the app grows in complexity", "Guarantee zero bugs automatically", "Replace the need for a backend server"], answer: 1, exp: "Structured state management becomes increasingly valuable as an app's UI and data interactions grow more complex." },
  { id: "ad-48", topic: "mobile-appdev", q: "An app's 'cold start' time refers to:", options: ["How long the battery lasts on a full charge", "How long the app takes to launch and become usable when it wasn't already running in memory, an important performance metric", "The time it takes to download the app initially", "The time between two consecutive app updates"], answer: 1, exp: "Cold start performance strongly affects perceived app responsiveness and is a common optimization target." },
  { id: "ad-49", topic: "mobile-appdev", q: "A key consideration when integrating third-party SDKs (analytics, ads, etc.) into a mobile app is:", options: ["They never have any impact on the app", "Their impact on app size, performance, privacy, and required permissions", "They automatically improve every aspect of the app with no trade-offs", "They cannot be removed once added"], answer: 1, exp: "Third-party SDKs can add meaningful overhead and introduce privacy/permission considerations that must be evaluated." },
  { id: "ad-50", topic: "mobile-appdev", q: "Overall, mobile app development involves balancing:", options: ["Only the choice of app icon color", "Platform capabilities and constraints, development cost/speed (native vs cross-platform), performance, and user experience to deliver a functional, maintainable app", "Nothing beyond writing code as fast as possible", "Only the app's file size, ignoring all other factors"], answer: 1, exp: "Successful mobile app development requires weighing these interconnected technical and product trade-offs together." },

  // ================= Mobile UI Design (50) =================
  { id: "ui-01", topic: "mobile-ui", q: "In mobile UI design, a comfortably tappable touch target is generally recommended to be at least around:", options: ["10x10 points/dp", "44x44 points (iOS) / 48x48 dp (Android)", "200x200 points/dp", "There is no recommended minimum size"], answer: 1, exp: "These platform guideline minimums help ensure targets are reliably tappable with a finger." },
  { id: "ui-02", topic: "mobile-ui", q: "The 'thumb zone' concept in mobile UI design refers to:", options: ["A setting that disables touch input", "The region of the screen most easily reached by a user's thumb while holding the device one-handed, which should ideally host frequently used controls", "A zone reserved exclusively for advertisements", "The area of the screen that cannot display any content"], answer: 1, exp: "Placing key actions within easy thumb reach improves comfort and usability, especially on larger phones." },
  { id: "ui-03", topic: "mobile-ui", q: "Material Design is:", options: ["Apple's design system for iOS", "Google's design system/guidelines primarily used for Android app UI, covering visual style, motion, and component behavior", "A cellular network standard", "A programming language"], answer: 1, exp: "Material Design provides a consistent visual and interaction language across Android apps." },
  { id: "ui-04", topic: "mobile-ui", q: "Apple's Human Interface Guidelines (HIG):", options: ["Are Google's Android design guidelines", "Provide design principles and conventions for building consistent, native-feeling iOS app interfaces", "Only apply to hardware design, never software", "Are a cellular network protocol"], answer: 1, exp: "Following HIG helps iOS apps feel familiar and consistent with the platform's conventions." },
  { id: "ui-05", topic: "mobile-ui", q: "A bottom navigation bar (tab bar) in a mobile app is typically used to:", options: ["Hide the app's most important features entirely", "Provide quick access to the app's top-level, most frequently used destinations/sections", "Display only advertisements", "Replace the need for any screen content"], answer: 1, exp: "Bottom nav bars keep primary navigation destinations persistently visible and easy to reach." },
  { id: "ui-06", topic: "mobile-ui", q: "A hamburger menu (☰ icon) in mobile UI typically:", options: ["Displays the app's most frequently used primary actions directly", "Hides secondary or less-frequently used navigation options behind a collapsible side panel, saving screen space", "Is a required element in every mobile UI", "Replaces the need for a home screen"], answer: 1, exp: "This pattern trades some discoverability for saving valuable screen real estate on secondary navigation." },
  { id: "ui-07", topic: "mobile-ui", q: "'Responsive design' in the context of UI generally means:", options: ["Layouts are completely fixed and never change", "Layouts fluidly adapt to different screen sizes using flexible grids/units, as opposed to fixed pixel layouts", "Only applies to desktop applications, never mobile", "A design that responds only to voice commands"], answer: 1, exp: "Responsive design lets one layout gracefully handle a range of screen sizes." },
  { id: "ui-08", topic: "mobile-ui", q: "'Adaptive design', as distinct from responsive design, typically means:", options: ["Exactly the same thing as responsive design with no distinction", "Providing distinct, tailored layouts for specific screen-size breakpoints/device categories, rather than one continuously fluid layout", "A design approach that ignores screen size entirely", "A design that changes randomly on each load"], answer: 1, exp: "Adaptive design serves a discrete set of layout variants rather than one continuously scaling layout." },
  { id: "ui-09", topic: "mobile-ui", q: "A 'swipe' gesture in mobile UI is commonly used to:", options: ["Only zoom in on content", "Navigate between screens/items (e.g., dismissing a notification, moving between pages) with a single directional finger drag", "Rotate the entire device physically", "Only trigger a long-press action"], answer: 1, exp: "Swipes are a fundamental, intuitive gesture for directional navigation and dismissal actions on touchscreens." },
  { id: "ui-10", topic: "mobile-ui", q: "A 'pinch-to-zoom' gesture requires:", options: ["Only single-finger input", "Multi-touch support, using two fingers moving apart or together to zoom in or out", "A physical zoom button on the device", "Voice command support"], answer: 1, exp: "This gesture relies on the touchscreen's ability to detect and track two simultaneous touch points." },
  { id: "ui-11", topic: "mobile-ui", q: "A 'long-press' (long tap) gesture is commonly used to:", options: ["Trigger the exact same action as a normal short tap", "Reveal additional options/context menus for an item, distinct from a normal short tap's primary action", "Permanently delete the app", "Only work on text fields"], answer: 1, exp: "Long-press provides a secondary interaction layer beyond the default single-tap action." },
  { id: "ui-12", topic: "mobile-ui", q: "Sufficient color contrast between text and its background in mobile UI design is important primarily for:", options: ["Purely decorative purposes with no functional benefit", "Readability and accessibility, especially for users with low vision or when viewing screens in bright sunlight", "Reducing the app's file size", "Increasing battery consumption intentionally"], answer: 1, exp: "Good contrast is a core accessibility and usability consideration, not just an aesthetic choice." },
  { id: "ui-13", topic: "mobile-ui", q: "'Dark mode' in mobile UI design provides:", options: ["A mode that disables all UI colors entirely", "An alternative color scheme with dark backgrounds and light text/elements, often reducing eye strain in low light and saving battery on OLED screens", "A mode exclusively for accessibility with no other benefit", "A feature that only exists on desktop software"], answer: 1, exp: "Dark mode has both a usability benefit (low-light comfort) and, on OLED screens, a potential battery-saving benefit." },
  { id: "ui-14", topic: "mobile-ui", q: "Microinteractions in UI design (e.g., a button's subtle animation on tap) primarily serve to:", options: ["Slow down the user's workflow deliberately", "Provide immediate, satisfying feedback confirming that a user's action was registered", "Replace the need for any functional UI elements", "Only exist for decorative purposes with no communicative value"], answer: 1, exp: "This immediate feedback reassures users their input was received, improving perceived responsiveness." },
  { id: "ui-15", topic: "mobile-ui", q: "A loading indicator (spinner, skeleton screen) in mobile UI serves to:", options: ["Hide the fact that content is loading", "Communicate to the user that content is being fetched/processed, reducing perceived wait time and uncertainty", "Permanently freeze the screen", "Replace the need for any actual content to ever load"], answer: 1, exp: "Clear loading feedback reduces user frustration and uncertainty during unavoidable waits." },
  { id: "ui-16", topic: "mobile-ui", q: "Good error-handling UX in a mobile app involves:", options: ["Silently failing with no explanation to the user", "Clearly explaining what went wrong and, where possible, how the user can resolve or retry, rather than a vague or silent failure", "Always crashing the app immediately", "Displaying only technical error codes with no plain-language explanation"], answer: 1, exp: "Clear, actionable error messages help users understand and recover from problems rather than feeling stuck." },
  { id: "ui-17", topic: "mobile-ui", q: "The distinction between UI (User Interface) and UX (User Experience) is that:", options: ["They are exactly the same concept with different names", "UI concerns the visual/interactive elements the user sees and touches, while UX concerns the user's overall experience, satisfaction, and ease of accomplishing their goals", "UX only applies to websites, never mobile apps", "UI is a subset of backend development with no relation to design"], answer: 1, exp: "UI is one important component contributing to the broader, more holistic concept of UX." },
  { id: "ui-18", topic: "mobile-ui", q: "'Information architecture' in app design refers to:", options: ["The physical hardware architecture of the device", "How content and features are organized, labeled and structured so users can find and navigate them logically", "Only the visual color palette used", "A type of database schema unrelated to UI"], answer: 1, exp: "Good information architecture ensures users can predictably locate the content/features they need." },
  { id: "ui-19", topic: "mobile-ui", q: "Consistency in mobile UI design (using the same patterns/components throughout an app) primarily benefits users by:", options: ["Making the app harder to learn", "Reducing the learning curve, since familiar patterns behave predictably across the app", "Guaranteeing the app looks identical to every other app", "Eliminating the need for any UI design at all"], answer: 1, exp: "Predictable, consistent patterns let users transfer their understanding from one part of the app to another." },
  { id: "ui-20", topic: "mobile-ui", q: "'Mobile-first' design philosophy means:", options: ["Designing only for desktop screens and ignoring mobile entirely", "Designing the interface for the smallest/most constrained (mobile) screen first, then progressively enhancing for larger screens", "Building the mobile app only after the desktop version is fully complete", "A philosophy that applies only to app icons"], answer: 1, exp: "Starting with the most constrained screen size helps prioritize essential content and functionality first." },
  { id: "ui-21", topic: "mobile-ui", q: "Accessibility features like screen reader support (e.g., VoiceOver on iOS, TalkBack on Android) in mobile UI design allow:", options: ["Only sighted users to interact with the app", "Visually impaired users to navigate and interact with the app via audible descriptions of on-screen elements", "The app to run faster on all devices", "The removal of all visual elements from the app"], answer: 1, exp: "Screen readers convert on-screen information into speech/braille output, letting visually impaired users use the app effectively." },
  { id: "ui-22", topic: "mobile-ui", q: "Supporting adjustable font/text scaling in a mobile app's UI is important because:", options: ["All users have identical visual needs", "Users with visual impairments may need larger text, and the app should remain usable/legible at different system font sizes", "Font scaling has no effect on usability", "It is purely a decorative feature with no functional purpose"], answer: 1, exp: "Respecting system-level text-size preferences is a key accessibility practice for mobile apps." },
  { id: "ui-23", topic: "mobile-ui", q: "A wireframe in the UI design process is:", options: ["A fully polished, final visual design ready for release", "A simplified, low-fidelity layout sketch/mockup used to plan the structure and placement of interface elements before visual design/development", "A type of automated test script", "A backend database schema"], answer: 1, exp: "Wireframes let designers/teams iterate on structure and flow quickly, before investing in detailed visuals." },
  { id: "ui-24", topic: "mobile-ui", q: "A prototype in the UI/UX design process:", options: ["Is always identical to the final shipped code", "Is an interactive (often clickable) mockup used to simulate and test the app's flow/behavior before full development", "Is only created after the app has already launched", "Is a type of marketing document with no interactivity"], answer: 1, exp: "Prototypes let teams validate flow and usability before committing to full engineering effort." },
  { id: "ui-25", topic: "mobile-ui", q: "Usability testing involves:", options: ["Only automated code analysis with no human involvement", "Observing real users attempting tasks with the app/prototype to identify points of confusion or friction in the design", "Testing only the app's server infrastructure", "Skipping all user feedback in favor of designer intuition"], answer: 1, exp: "Direct observation of real users often reveals usability problems that internal team reviews miss." },
  { id: "ui-26", topic: "mobile-ui", q: "Onboarding screens in a mobile app's UI design primarily aim to:", options: ["Confuse new users intentionally", "Help new users quickly understand the app's core value and how to get started", "Replace the need for the app's main functionality", "Only appear for returning, experienced users"], answer: 1, exp: "Effective onboarding smooths a new user's first experience and improves early retention." },
  { id: "ui-27", topic: "mobile-ui", q: "A 'call to action' (CTA) button in mobile UI design should typically be:", options: ["Hidden from view to avoid distracting the user", "Visually prominent and clearly labeled, guiding the user toward the primary intended action on that screen", "The smallest element on the screen", "Identical in style to every other button, with no visual distinction"], answer: 1, exp: "A clear, prominent CTA helps guide users toward the screen's most important intended action." },
  { id: "ui-28", topic: "mobile-ui", q: "Whitespace (negative space) in mobile UI design is used to:", options: ["Waste valuable screen space with no benefit", "Improve readability and visual clarity by giving elements room to breathe, rather than crowding the small screen", "Always be filled with additional content", "Indicate an error state"], answer: 1, exp: "Thoughtful whitespace helps content feel organized and reduces visual clutter, especially valuable on small screens." },
  { id: "ui-29", topic: "mobile-ui", q: "A 'card' UI pattern, commonly seen in mobile apps, presents:", options: ["An entire app's functionality within a single unbounded element", "A self-contained, often tappable block of related content (image, text, actions) as a distinct visual unit", "Only plain text with no visual boundaries", "A hidden element never shown to users"], answer: 1, exp: "Cards are a popular pattern for organizing scannable, related chunks of content (e.g., in feeds or lists)." },
  { id: "ui-30", topic: "mobile-ui", q: "Designing for 'one-handed use' on mobile devices primarily considers:", options: ["Placing all controls at the very top of the screen regardless of reachability", "Placing frequently used interactive elements within comfortable thumb reach given typical device sizes", "Requiring users to always use both hands", "Ignoring device size entirely"], answer: 1, exp: "This directly relates to the 'thumb zone' concept, since many users operate their phones with one hand." },
  { id: "ui-31", topic: "mobile-ui", q: "A common mobile UI anti-pattern is:", options: ["Providing generous spacing between interactive elements", "Placing critical interactive controls too close together, causing accidental taps ('fat finger' errors)", "Using clear, legible typography", "Providing helpful error messages"], answer: 1, exp: "Cramped touch targets are a frequent source of frustrating accidental taps on small mobile screens." },
  { id: "ui-32", topic: "mobile-ui", q: "Progressive disclosure, as a UI design principle, means:", options: ["Showing every possible option to the user immediately, all at once", "Revealing information/options gradually as needed, rather than overwhelming the user with everything at once", "Hiding all information permanently with no way to access it", "Randomly displaying unrelated content"], answer: 1, exp: "This principle helps keep interfaces simpler and less overwhelming, especially on small screens." },
  { id: "ui-33", topic: "mobile-ui", q: "A skeleton screen (gray placeholder shapes shown while content loads) is often preferred by designers over a plain spinner because it:", options: ["Hides all information about the page's eventual structure", "Gives users a sense of the page's structure and a perceived faster loading experience, rather than just an abstract 'waiting' indicator", "Always loads slower than a spinner", "Is purely decorative with no usability benefit"], answer: 1, exp: "Skeleton screens can improve perceived performance by previewing the layout users are about to see." },
  { id: "ui-34", topic: "mobile-ui", q: "Platform-consistent iconography (using recognizable, standard icons) in mobile UI design helps:", options: ["Force users to learn entirely new symbols for every app", "Users quickly understand an icon's function without needing to learn app-specific symbols", "Reduce the app's accessibility", "Guarantee the app requires no labels ever"], answer: 1, exp: "Leveraging widely recognized icon conventions reduces cognitive load for users familiar with the platform." },
  { id: "ui-35", topic: "mobile-ui", q: "Feedback for a failed form submission in mobile UI design should ideally:", options: ["Simply display a generic 'error occurred' message with no further detail", "Highlight the specific problematic field(s) with a clear message, rather than a generic notice", "Silently discard the user's entered data with no explanation", "Reload the entire app from scratch"], answer: 1, exp: "Specific, actionable feedback helps users quickly correct the actual problem rather than guessing." },
  { id: "ui-36", topic: "mobile-ui", q: "A 'floating action button' (FAB), a Material Design pattern, is typically used for:", options: ["Every possible action on a screen, with no prioritization", "A screen's single, most important/primary action, visually emphasized and persistently accessible", "Only decorative purposes with no function", "Navigation between unrelated apps"], answer: 1, exp: "FABs draw attention to one clear primary action (e.g., 'compose' or 'add new item') on a given screen." },
  { id: "ui-37", topic: "mobile-ui", q: "Designing tap targets with adequate spacing between them primarily reduces:", options: ["Screen brightness", "Accidental mis-taps, improving usability especially for users with larger fingers or motor impairments", "The app's total file size", "Network latency"], answer: 1, exp: "Adequate spacing is a key part of designing reliably tappable, accessible touch interfaces." },
  { id: "ui-38", topic: "mobile-ui", q: "Testing a mobile UI design across multiple screen sizes and device types before release is important because:", options: ["A design that looks good on one device always looks good on every device automatically", "A design that looks good on one device/resolution may break or look poor on others without proper responsive/adaptive handling", "Screen size variation has no impact on UI appearance", "Only the largest available device needs to be tested"], answer: 1, exp: "Cross-device testing helps catch layout issues that only appear at certain screen sizes/resolutions." },
  { id: "ui-39", topic: "mobile-ui", q: "The WCAG (Web Content Accessibility Guidelines), though originally web-focused, influence mobile UI design accessibility practices by:", options: ["Having no relevance to mobile app design whatsoever", "Providing widely referenced standards for contrast, text sizing, and interactive element accessibility", "Only applying to text color, with no other guidance", "Mandating a specific programming language for all apps"], answer: 1, exp: "Many mobile accessibility best practices draw on the same underlying principles codified in WCAG." },
  { id: "ui-40", topic: "mobile-ui", q: "A 'pull-to-refresh' gesture pattern in mobile UI:", options: ["Permanently deletes the current screen's content", "Lets users manually trigger a content refresh by pulling down on a scrollable list/view, typically showing a loading indicator during the refresh", "Only works when the device is offline", "Requires a physical refresh button on the device"], answer: 1, exp: "This gesture-based pattern has become a widely recognized convention for manually refreshing list-based content." },
  { id: "ui-41", topic: "mobile-ui", q: "Reducing the number of steps/taps required to complete a common task ('minimizing friction') in mobile UI design generally:", options: ["Decreases usability and completion rates", "Improves usability and completion rates for that task", "Has no measurable effect on user behavior", "Only matters for desktop applications"], answer: 1, exp: "Streamlined flows with fewer steps typically lead to higher task completion rates on mobile." },
  { id: "ui-42", topic: "mobile-ui", q: "Empty states (screens shown when there's no content yet, e.g., an empty inbox) in good mobile UI design should:", options: ["Simply display a blank, unexplained screen", "Explain why the screen is empty and, where relevant, guide the user toward an action to populate it", "Always show an error message even when nothing is actually wrong", "Be avoided entirely by never letting a screen have zero content"], answer: 1, exp: "Thoughtful empty states turn a potentially confusing moment into a helpful, guiding one." },
  { id: "ui-43", topic: "mobile-ui", q: "Designing UI text (labels, buttons, messages) with clear, concise language is important in mobile UI design because:", options: ["Small screens have limited space, and users often scan quickly rather than reading thoroughly", "Longer, more detailed text always performs better on mobile", "Text length has no impact on mobile usability", "Users prefer to read lengthy paragraphs on small screens"], answer: 0, exp: "Concise, scannable text respects both limited screen space and typical mobile reading behavior." },
  { id: "ui-44", topic: "mobile-ui", q: "A modal dialog in mobile UI design is typically used to:", options: ["Blend seamlessly into the background with no visual distinction", "Interrupt the current flow to demand the user's immediate attention/decision (e.g., a confirmation), and should be used sparingly to avoid annoying users", "Replace the app's main navigation entirely", "Only be used for purely decorative purposes"], answer: 1, exp: "Overusing modals can frustrate users, so they're best reserved for genuinely important interruptions." },
  { id: "ui-45", topic: "mobile-ui", q: "Animation/transition design between screens in mobile UI, when used purposefully, helps:", options: ["Confuse users about screen relationships", "Orient users by visually communicating spatial/hierarchical relationships between screens (e.g., where a new screen 'came from')", "Always slow down the app with no benefit", "Replace the need for any navigation structure"], answer: 1, exp: "Purposeful motion design can reinforce a mental model of how screens relate to one another." },
  { id: "ui-46", topic: "mobile-ui", q: "A common mobile design guideline is to avoid relying on color alone to convey important information (e.g., error vs success) because:", options: ["Color is always sufficient for every user", "Some users are colorblind, so an icon/text cue should accompany the color to remain accessible", "Color has no meaning in UI design", "Using icons alongside color is against platform guidelines"], answer: 1, exp: "Pairing color with icons/text ensures the information is accessible to colorblind users too." },
  { id: "ui-47", topic: "mobile-ui", q: "Designing for varying network conditions (slow/unreliable mobile connections) in the UI layer includes:", options: ["Assuming a perfect, always-fast connection at all times", "Showing appropriate loading/offline states rather than leaving the user staring at a frozen or blank screen", "Disabling the app entirely whenever connectivity is imperfect", "Ignoring network state entirely in the UI"], answer: 1, exp: "Explicit UI states for loading/offline conditions keep users informed rather than confused by an unresponsive app." },
  { id: "ui-48", topic: "mobile-ui", q: "A 'hit slop' or expanded touch area around a small visual icon in mobile UI design is used to:", options: ["Visually enlarge the icon itself permanently", "Make a visually small element easier to tap accurately without needing to visually enlarge the icon itself", "Disable the icon's tap functionality entirely", "Reduce the icon's touch responsiveness"], answer: 1, exp: "This technique keeps the visual design compact while still meeting minimum comfortable touch-target sizing." },
  { id: "ui-49", topic: "mobile-ui", q: "Conducting a heuristic evaluation (reviewing a UI against established usability principles) is a method used to:", options: ["Replace the need for any design process entirely", "Identify potential usability issues in a design without necessarily needing full user testing", "Guarantee a design has zero usability problems", "Only evaluate visual color choices"], answer: 1, exp: "Heuristic evaluation is a relatively fast, low-cost way to catch common usability issues, often as a complement to (not full replacement for) user testing." },
  { id: "ui-50", topic: "mobile-ui", q: "Overall, effective mobile UI design balances:", options: ["Only the developer's personal visual preferences", "Platform conventions, accessibility, touch ergonomics, and clear visual hierarchy to create an interface that is both usable and pleasant on small, touch-based screens", "Maximizing visual complexity regardless of usability", "Ignoring platform guidelines entirely for a unique look"], answer: 1, exp: "These combined considerations are what distinguish genuinely well-designed mobile interfaces from merely decorative ones." }

);
